SELECT count(*)
FROM Player_Attributes
WHERE preferred_foot = 'left' AND crossing = (SELECT MAX(crossing) FROM Player_Attributes WHERE preferred_foot = 'left');

SELECT SUM(T1.Consumption)
FROM yearmonth AS T1
WHERE T1.CustomerID = 6 AND T1.Date BETWEEN '201308' AND '201311';

SELECT
  SUM(CASE WHEN PLT < 100 THEN 1 ELSE 0 END) - SUM(CASE WHEN PLT > 400 THEN 1 ELSE 0 END)
FROM Laboratory;

SELECT MAX(Consumption)
FROM yearmonth
WHERE Date LIKE '2012%';
